INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111042, 'spa', 'Alcanzar, llegar, arribar', 'Alcanzar, llegar o arribar, abarcando extensión espacial, llegada temporal y el acaecimiento de sucesos. Se usa del gran árbol que alcanzaba el cielo (Dan 4:11, 20), de un decreto que sobrevino a Nabucodonosor (Dan 4:24, 28), de uno semejante a un hijo de hombre que llegó ante el Anciano de Días (Dan 7:13), del tiempo señalado que arribó (Dan 7:22) y de hombres arrojados a un foso (Dan 6:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111050, 'spa', 'tribu, clan', 'La acepción más frecuente (183 apariciones), designando una división tribal hereditaria, especialmente de Israel. El árabe سِبْط y el coreano 지파 seleccionan vocabulario dedicado de ''tribu'', confirmando lexicalización plena distinta de ''vara''. Dominante en los censos y repartos tribales de Números 1-4, Josué 13-21 y 1 Reyes 7-8.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111057, 'spa', 'vara, cayado, cetro', 'Bastón, vara o cetro de madera (63 apariciones): el objeto concreto del que deriva la metáfora tribal. La vara de Moisés ante la zarza ardiente (Éx 4:2), la vara florecida de Aarón (Nm 17:8) y las varas de los magos del Faraón (Éx 7:12) emplean esta acepción. Puede denotar bastón de caminante, vara de autoridad o cetro real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111072, 'spa', 'rama, brote', 'Rama o brote botánico (4 apariciones), restringido a Ezequiel 19:11-14 donde las ramas vigorosas de una vid —aptas para cetro de gobernante— son arrancadas y marchitadas. La superposición figurativa —ramas que representan poder real— convierte esta acepción en un puente semántico entre la vara concreta y la tribu metafórica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111093, 'spa', 'vara adivinatoria', 'Uso arcaico raro (2 apariciones) en Habacuc 3:9, 14 para varas o astiles de flecha asociados con la guerra divina o el sorteo. El árabe سِهَام (''flechas'') y el suajili mishale sugieren instrumentos de sortición o combate más que bastones ordinarios. El difícil texto de Hab 3:14 ha desconcertado a los comentaristas, apuntando a un ámbito sacral arcaico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111105, 'spa', 'Hacia abajo, abajo, debajo', 'Hacia abajo, abajo, debajo: adverbio de dirección espacial que significa ''hacia abajo,'' ''abajo'' o ''debajo,'' derivado de נָטָה (''extender, inclinar'') con la terminación locativa he. Frecuentemente emparejado con מַעְלָה (''hacia arriba'') para expresar el eje vertical completo. Usado con preposiciones en descripciones arquitectónicas del tabernáculo (Éx 26:24; 27:5; 38:4), en las maldiciones del pacto de declive progresivo (Dt 28:13, 43), y en imágenes proféticas de echar raíces hacia abajo (Is 37:31; 2 R 19:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111113, 'spa', 'La cama o lecho ordinario usado para dormir, descansar, recostarse durante la en', 'La cama o lecho ordinario usado para dormir, descansar, recostarse durante la enfermedad o reposar. Abarca la gran mayoría de las ocurrencias: desde el lecho de muerte de Jacob (Gn 47:31; 48:2; 49:33) hasta el mobiliario del cuarto de huéspedes de Eliseo (2 R 4:10, 21, 32) y los lujosos lechos de marfil condenados por Amós (Am 6:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111126, 'spa', 'Féretro o angarillas', 'Féretro o angarillas: una estructura portátil para llevar un cadáver al entierro. Solo una ocurrencia clara: David ordena a Joab y a todo el pueblo caminar detrás del féretro de Abner (2 S 3:31). La extensión semántica es natural: la última ''cama'' del difunto se convierte en su transporte final.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111129, 'spa', 'Litera real o silla de manos', 'Litera real o silla de manos: un vehículo tipo cama portado por sirvientes para una persona viva de alto rango. Cantares 3:7 describe la litera de Salomón rodeada de sesenta guerreros, claramente no una cama para dormir sino un elaborado palanquín para desfiles ceremoniales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111134, 'spa', 'Tesoro escondido', 'Tesoro oculto o enterrado: algo de valor deliberadamente escondido bajo tierra o en un lugar secreto. Se usa literalmente del dinero en los costales (Gn 43:23), provisiones almacenadas en un campo (Jer 41:8) y el botín prometido a Ciro (Is 45:3), y figuradamente de la sabiduría como objeto de búsqueda (Pr 2:4) y de la muerte anhelada más que cualquier riqueza (Job 3:21).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111135, 'spa', 'Plantío, plantación', 'Plantío o plantación en contextos proféticos, tanto literal como figurado. Literalmente designa viñas (Miq 1:6) y terrenos cultivados (Ez 17:7; 31:4). Figuradamente, Isaías lo aplica al pueblo de Dios como «plantío de Jehová» (Isa 60:21; 61:3), expresando pertenencia divina y expectativa de justicia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111142, 'spa', 'Manjar, delicia', 'Alimento sabroso o exquisito, manjares preparados con especial cuidado para agradar el paladar. Figura prominentemente en la narrativa de Isaac, Esaú y Jacob, donde Isaac solicita manjares de caza como preludio a la bendición patriarcal (Gn 27:4, 7, 9, 14, 17, 31). En Proverbios 23:3, 6 el término adquiere un matiz de advertencia: los manjares de un gobernante pueden ser engañosos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111145, 'spa', 'Ser llovido (Nifal)', 'Ser llovido (Nifal): sentido pasivo (Nifal): ser llovido, recibir lluvia — describiendo una tierra o región que experimenta o no experimenta precipitación. Ambas apariciones se encuentran en Amós 4:7 en un contraste impactante: una porción de tierra ''recibía lluvia'' mientras otra se marchitaba por su falta. Este sentido raro completa el espectro semántico del verbo desde el causativo activo hasta la recepción pasiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111146, 'spa', 'Hacer llover juicio (Hifil)', 'Hacer llover juicio (Hifil): sentido de juicio divino (Hifil): hacer llover sustancias destructivas — fuego, azufre, trampas, carbones encendidos — desde el cielo como acto de castigo catastrófico. El texto paradigmático es Génesis 19:24, donde el SEÑOR hace llover azufre y fuego sobre Sodoma y Gomorra. El Salmo 11:6 extiende la imagen a trampas, fuego y viento abrasador llovidos sobre los malvados, y el Salmo 78:24-27 relata maná y codornices llovidos como provisión.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111147, 'spa', 'Hacer llover (Hifil)', 'Hacer llover (Hifil): sentido meteorológico causativo (Hifil): hacer llover, enviar lluvia — con Dios como sujeto implícito o explícito controlando el clima literal. Génesis 2:5 y 7:4 establecen el patrón en la narrativa primordial, mientras Amós 4:7 repite la imagen tres veces al describir la lluvia selectiva de Dios. Éxodo 9:18 y 16:4 lo extienden tanto al maná como al granizo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111159, 'spa', 'Lluvia o aguaceros como precipitación del cielo, enmarcada predominantemente com', 'Lluvia o aguaceros como precipitación del cielo, enmarcada predominantemente como bendición agrícola otorgada por Dios o retenida como castigo pactual. La fórmula característica es natan matar (''dar lluvia'', Dt 11:14; 28:12; 1 R 8:36), vinculando la lluvia con la soberanía divina sobre la tierra. Emparejada con tal (''rocío'') en 1 Reyes 17:1 y con yoreh y malqosh (''lluvia temprana y tardía'') en Deuteronomio, la palabra abarca todo el ciclo estacional de precipitaciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111170, 'spa', 'Guardia, patio de la guardia', 'Guardia, patio de la guardia: guardia, casa de guardia o patio de la guardia, referido a una instalación de detención o recinto custodiado dentro de un complejo real o administrativo. Casi todas las apariciones se encuentran en la narrativa del encarcelamiento de Jeremías en el ''patio de la guardia'' (Jer 32:2, 8, 12; 33:1; 37:21; 38:6, 13, 28; 39:14-15), con Nehemías añadiendo referencias tanto a un patio como a una puerta de la guardia (Neh 3:25; 12:39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111171, 'spa', 'Blanco, diana', 'Blanco, diana: blanco o diana colocada para disparar, basado en el sentido raíz de vigilar o fijar la mirada en algo. Usado figuradamente en Job 16:12, donde Job protesta que Dios lo ha puesto como blanco, y en Lamentaciones 3:12, ''como blanco para la flecha.'' El único uso literal aparece en 1 Samuel 20:20, la escena de la señal con flechas de Jonatán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111178, 'spa', 'interrogativo ¿quién?', 'El interrogativo directo ''¿quién?'' o ''¿a quién?'': la acepción dominante (413 de 423 apariciones). Funciona como sujeto u objeto en preguntas sobre identidad personal, a menudo con prefijos preposicionales (a quién, de quién). Pasajes clave: la pregunta de Dios en Gn 3:11 y la queja del Faraón en Éx 5:2: ''¿Quién es el SEÑOR?''');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111186, 'spa', 'indefinido quienquiera', 'El valor indefinido o generalizador ''quienquiera que'', ''todo el que'' (10 apariciones), presente en cláusulas condicionales o relativas donde la identidad de la persona queda abierta. El alemán und-wer y el francés quiconque resaltan este desplazamiento de pregunta específica a invitación abierta. Notable en Éx 32:33 (la convocatoria de Moisés) y 2 S 20:11 (el grito de reunión de Joab).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111206, 'spa', 'Ciudad moabita', 'Nombre propio de una ciudad en la meseta de Moab, al este del mar Muerto. Asignada a Ruben en el reparto tribal (Jos 13:9, 16), sirvio como punto de reunion militar para los amonitas (1 Cr 19:7). La LXX la transcribe como Maidaba o Medaba. La Inscripcion de Mesa (linea 8) confirma su relevancia historica como enclave disputado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111210, 'spa', 'Lo mejor de', 'La porción más selecta y fina de algo, siempre en estado constructo («lo mejor de X»), funcionando como superlativo. En el Código de la Alianza, la restitución debe provenir de «lo mejor de su campo y lo mejor de su viña» (Éx 22:4), estableciendo un estándar legal de compensación de máxima calidad. Faraón ofrece a la familia de José «lo mejor de la tierra» de Egipto (Gén 47:6, 11), señalando generosidad real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111213, 'spa', 'Nombre propio masculino', 'Nombre propio masculino llevado por múltiples individuos, siendo el más destacado el hijo de Mefiboset, que continuó el linaje de Saúl, y varios levitas del período de la restauración. Su aparición en contextos tan diversos como el linaje real, el servicio levítico y la renovación del pacto demuestra que era un nombre de uso común en la sociedad israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111214, 'spa', 'Miguel (nombre propio)', 'Miguel (nombre propio): nombre propio masculino מִיכָאֵל (''¿Quién como Dios?''), que designa a múltiples individuos: líderes tribales y militares (Nm 13:13; 1 Cr 5:13-14; 7:3; 8:16; 12:20; 27:18), levitas (1 Cr 6:40), miembros de la realeza (2 Cr 21:2), un retornado postexílico (Esd 8:8), y sobre todo el ''príncipe'' arcangélico que defiende a Israel en las visiones apocalípticas de Daniel (Dn 10:13, 21; 12:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111218, 'spa', 'Nombre propio que significa ''¿Quién es como YHWH?'' llevado por múltiples persona', 'Nombre propio que significa ''¿Quién es como YHWH?'' llevado por múltiples personajes bíblicos. El efrateo Miqueas de Jueces 17-18 estableció un santuario privado con un ídolo y un levita contratado, ilustrando el desorden religioso premonárquico. El profeta Miqueas de Moreset (Mi 1:1) pronunció oráculos contra Samaria y Jerusalén; Jeremías 26:18 cita su profecía. Otros portadores incluyen un descendiente de Saúl (1 Cr 8:34) y varias figuras levíticas y cortesanas en Crónicas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111223, 'spa', 'Nombre propio masculino', 'Nombre propio masculino que significa ''?Quien es como Yah(ve)?'' — grafia alternativa o mas completa de Miqueas. En espanol se traduce Micaias o Micayas. Se aplica al profeta Miqueas en Jer 26:18 (Ketiv), a dos levitas en Nehemias 12:35 y 12:41, y a un cortesano en 2 Reyes 22:12. La alternancia Micaias/Miqueas en textos paralelos refleja la fluidez ortografica hebrea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111224, 'spa', 'El nombre propio מִיכָיְהוּ (Micaías), nombre teofórico que significa ''¿quién es', 'El nombre propio מִיכָיְהוּ (Micaías), nombre teofórico que significa ''¿quién es como YHWH?''. Lo lleva principalmente el profeta Micaías hijo de Imlá, quien se mantuvo solo frente a los cuatrocientos profetas cortesanos de Acab para entregar un oráculo desfavorable antes de la campaña en Ramot de Galaad (1 R 22:8–28; 2 Cr 18:7–27). También un efraimita del período de los Jueces (Jue 17:1, 4) y una figura en tiempos de Jeremías (Jer 36:11, 13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111228, 'spa', 'El nombre propio femenino de la hija menor de Saúl, quien se casó con David por ', 'El nombre propio femenino de la hija menor de Saúl, quien se casó con David por amor genuino (1 S 18:20). Desempeña un papel crucial en el conflicto David-Saúl, ayudando a David a escapar (1 S 19:11-13) y convirtiéndose después en peón político (1 S 25:44; 2 S 3:13-14). Su escena final, despreciando la adoración extática de David ante el arca (2 S 6:16-23), cierra su arco narrativo con una irónica distancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111232, 'spa', 'agua, aguas', 'El agua como sustancia física en todas sus manifestaciones naturales y rituales: agua potable, de pozo y manantial, de ríos y mares, lluvia, aguas de diluvio y agua de purificación. Con 582 apariciones es virtualmente la única acepción operativa. Las 43 lenguas meta la rinden con su sustantivo primario para agua, confirmando la universalidad del concepto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111274, 'spa', 'variante textual anómala', 'Una única aparición anómala en Is 44:24, marcada por una discrepancia Ketiv/Qere donde el texto consonántico difiere de la lectura esperada. Varias traducciones lo rinden como ''agua'', aunque el español muestra ''[quién]'', apuntando a una posible lectura alternativa מִי (''quién'') en lugar de מַיִם (''agua''). Es un artefacto de crítica textual, no una acepción semántica distinta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111289, 'spa', 'Nombre sacerdotal propio', 'Nombre propio masculino asociado con familias sacerdotales a lo largo de múltiples generaciones. Los diversos portadores de este nombre en distintos contextos —divisiones sacerdotales, exiliados que retornaron, firmantes del pacto— sugieren que era un nombre tradicional dentro de los círculos sacerdotales, preservado con variantes ortográficas como Mijamín, Miyamín y Miímin.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111290, 'spa', 'Categoría biológica o taxonómica que designa un tipo distinto de planta o animal', 'Categoría biológica o taxonómica que designa un tipo distinto de planta o animal. Aparece siempre con la preposición le- y un sufijo posesivo (''según su especie''). En Génesis 1:11-25 estructura toda la taxonomía de la creación; en Levítico 11 y Deuteronomio 14 organiza las listas de pureza alimentaria. La palabra implica límites divinamente establecidos entre las especies, no una taxonomía científica moderna, sino un orden creacional que Dios mismo instituyó.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111295, 'spa', 'Estrujar, presionar', 'Las traducciones identifican la acción de prensar o estrujar: español ''batir'' (prensar/agitar). Proverbios 30:33 emplea esta palabra tres veces en estructura paralela, creando un proverbio memorable sobre causa y efecto. Así como estrujar la leche o la nariz produce resultados predecibles (cuajada y sangre), presionar o provocar la ira produce contienda. La triple repetición refuerza la inevitabilidad de las consecuencias.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111297, 'spa', 'Misael (nombre propio)', 'Nombre propio Misael («¿quién es lo que Dios es?»), referido a tres figuras bíblicas: (a) hijo de Uziel, primo de Moisés, que retiró los cuerpos de Nadab y Abiú (Éx 6:22; Lv 10:4); (b) compañero de Daniel en Babilonia, renombrado Mesac (Dn 1:6-7; 2:17); (c) líder junto a Esdras en la lectura de la Ley (Neh 8:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111301, 'spa', 'Llanura geográfica, meseta o altiplano, especialmente la región elevada de Trans', 'Llanura geográfica, meseta o altiplano, especialmente la región elevada de Transjordania entre el Arnón y Hesbón. Deuteronomio 3:10 y Josué 13:9-21 anclan este sentido en una topografía concreta, contrastando la llanura con la zona montañosa y el valle.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111304, 'spa', 'Terreno llano y parejo entendido figuradamente como un camino seguro y libre de ', 'Terreno llano y parejo entendido figuradamente como un camino seguro y libre de obstáculos y peligros. Los Salmos piden a Dios un camino recto (Sal 27:11; 143:10), e Isaías 40:4 promete que los lugares torcidos se enderezarán. La metáfora proyecta el terreno físico sobre la experiencia de la guía y protección divinas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111309, 'spa', 'Rectitud, equidad o justicia en contextos morales y judiciales, la extensión abs', 'Rectitud, equidad o justicia en contextos morales y judiciales, la extensión abstracta de la nivelación física hacia la rectitud ética. El Salmo 45:6 habla de un cetro de equidad, Isaías 11:4 de juzgar a los pobres con justicia, y Malaquías 2:6 de andar con Dios en paz y rectitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111315, 'spa', 'Mesac (nombre propio)', 'Mesac (nombre propio): nombre propio מֵישַׁךְ (arameo), el nombre cortesano babilónico dado al exiliado judío Misael (Dn 1:7). Las catorce apariciones se concentran en Daniel 2:49 y el capítulo 3, donde sirve como administrador provincial y soporta el horno de fuego ardiente por negarse a la idolatría. Siempre se menciona en la tríada Sadrac, Mesac y Abed-nego.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111318, 'spa', 'Rectitud, equidad o integridad — la cualidad ética de ser moralmente recto en la', 'Rectitud, equidad o integridad — la cualidad ética de ser moralmente recto en la conducta, los juicios o el habla. Este sentido abrumadoramente dominante (15 ocurrencias) impregna la poesía litúrgica y la enseñanza sapiencial. El Salterio declara repetidamente que Dios juzga a los pueblos ''con equidad'' (Sal 9:8; 96:10; 98:9; 99:4), mientras que Proverbios asocia מֵישָׁרִים con la justicia (צֶדֶק, Pr 1:3; 2:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111322, 'spa', 'Suavidad o uniformidad en sentido físico o sensorial — describiendo un camino ll', 'Suavidad o uniformidad en sentido físico o sensorial — describiendo un camino llano o el fluir suave de un líquido. Tres ocurrencias conservan esta dimensión concreta: el camino del justo es ''llano'' en Isaías 26:7, el vino baja ''suavemente'' en Proverbios 23:31, y el beso del amado fluye ''suavemente'' sobre labios y dientes en Cantares 7:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111332, 'spa', 'Un acuerdo equitativo o pacto entre partes — extensión del sentido de equidad al', 'Un acuerdo equitativo o pacto entre partes — extensión del sentido de equidad al ámbito de la diplomacia y los tratados. Una única ocurrencia clara en Daniel 11:6, donde el rey del Sur y el rey del Norte ''hacen un arreglo equitativo'' (עָשָׂה מֵישָׁרִים).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111334, 'spa', 'Cuerda de tienda', 'Sentido principal de cuerda o soga usada para estacar y asegurar una tienda o la estructura del tabernáculo. La fuente sacerdotal concentra la mayoría de las apariciones (Éx 35:18; 39:40; Nm 3:26, 37; 4:26, 32), catalogando los מֵיתָרִים como equipamiento esencial del tabernáculo junto con estacas y armazones. El uso profético transforma la imagen: las cuerdas rotas de Jeremías simbolizan ruina nacional (Jer 10:20), mientras que las cuerdas extendidas de Isaías señalan expansión divina (Is 54:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111339, 'spa', 'Cuerda de arco', 'Sentido especializado que designa la cuerda de un arco: la cuerda tensa de un arma, no de una tienda. El Salmo 21:13 representa a Dios preparando su arco contra sus enemigos: «apuntarás con tus cuerdas (בְּמֵיתָרֶיךָ) a sus rostros». El vínculo semántico con las cuerdas de tienda reside en la noción común de cuerda tensada y estirada, pero el contexto bélico y su única atestiguación la distinguen como sentido aparte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111340, 'spa', 'Dolor físico o angustia emocional experimentados por individuos o comunidades', 'Dolor físico o angustia emocional experimentados por individuos o comunidades. Introducido como el reconocimiento divino del sufrimiento de Israel en la esclavitud egipcia (Éx 3:7), se extiende luego a la aflicción corporal (Job 33:19; 2 Cr 6:29), los tormentos que se multiplican para los malvados (Sal 32:10), el pesar ligado a las consecuencias del pecado (Sal 38:18; 69:27), el dolor que acompaña al conocimiento (Ec 1:18; 2:23), y la descripción suprema del Siervo Sufriente como ''varón de dolores'' (Is 53:3-4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111357, 'spa', 'Enrejado, rejilla metálica', 'Celosía o rejilla de bronce construida como parte del altar del holocausto del tabernáculo. El término aparece exclusivamente en las instrucciones y relatos de construcción de Éxodo, siempre en conexión con el altar. Éxodo 27:4 especifica «le harás un enrejado, obra de rejilla de bronce» (מִכְבָּר מַעֲשֵׂה רֶשֶׁת נְחֹשֶׁת), colocado alrededor de la mitad inferior del altar (27:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111361, 'spa', 'golpe, azote', 'golpe, azote');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111362, 'spa', 'plaga, calamidad', 'plaga, calamidad');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111364, 'spa', 'herida, lesión', 'herida, lesión');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111366, 'spa', 'matanza, derrota', 'matanza, derrota');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111393, 'spa', 'Quemadura cutanea', 'Mancha o cicatriz en la piel causada por el fuego, usada exclusivamente en el codigo de pureza levitico (Lv 13:24-28). El sacerdote evalua si la quemadura (מִכְוַת־אֵשׁ, ''quemadura de fuego'') presenta signos de enfermedad cutanea en expansion. El termino esta estrictamente limitado a este contexto diagnostico sacerdotal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111394, 'spa', 'Morada fija y establecida — el lugar preparado de la residencia de Dios', 'Morada fija y establecida — el lugar preparado de la residencia de Dios. El Cántico del Mar celebra el santuario como el מָכוֹן que las manos de Dios establecieron (Éx 15:17). La oración de dedicación de Salomón invoca repetidamente ''el lugar de tu morada'' en el cielo (1 R 8:39, 43, 49), e Isaías se refiere a ''mi lugar de reposo'' (Is 18:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111396, 'spa', 'Fundamento o base establecida sobre la cual algo descansa, usado metafóricamente', 'Fundamento o base establecida sobre la cual algo descansa, usado metafóricamente del orden moral y cósmico. Salmo 89:14 y 97:2 declaran que ''justicia y derecho son el מְכוֹן de su trono'', retratando el gobierno de Dios como fundado sobre una roca ética inamovible. Salmo 104:5 extiende esto a la creación misma: Dios asentó la tierra sobre sus fundamentos (מְכוֹנֶיהָ).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111403, 'spa', 'Soporte fijo, basa o pedestal, predominantemente las diez basas de bronce con ru', 'Soporte fijo, basa o pedestal, predominantemente las diez basas de bronce con ruedas que Salomón mandó fabricar para las pilas del templo (1 R 7:27-43), decoradas con paneles grabados de leones, bueyes y querubines. También la base del altar reconstruido tras el exilio (Esd 3:3) y el lugar de reposo para el efa simbólico en la visión de Zacarías (Zac 5:11). La raíz כּוּן (''estar establecido'') resalta la permanencia y estabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111411, 'spa', 'Origen, procedencia', 'La evidencia multilingüe apunta a origen y procedencia: español ''origen''. Ezequiel 16:3 confronta a Jerusalén con sus orígenes en tierra cananea, desafiando toda presunción de superioridad inherente. Ezequiel 21:30 promete juicio en la tierra natal de Faraón. Ezequiel 29:14 predice la restauración de Egipto a Patros, su tierra de origen, pero solo como un reino humilde.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111413, 'spa', 'Nombre propio masculino Makir, referido principalmente al hijo mayor de Manasés,', 'Nombre propio masculino Makir, referido principalmente al hijo mayor de Manasés, cuyo clan conquistó Galaad y recibió su territorio al oriente del Jordán (Gn 50:23; Nm 26:29; 32:39–40; Dt 3:15; Jos 13:31; 17:1). En Jueces 5:14 ''Makir'' funciona como designación tribal de Manasés. Un segundo Makir, hijo de Amiel de Lo-debar, aparece en 2 Samuel 9:4–5 como anfitrión de Mefi-boset y proveedor de David durante la rebelión de Absalón (2 S 17:27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111419, 'spa', 'Hundirse, ser humillado', 'Las traducciones multilingües señalan rebajamiento y humillación: español ''fueron abatidos, son abatidos''. El Salmo 106:43 lamenta el ciclo repetido de rebelión de Israel que conduce a la humillación bajo sus enemigos. Job 24:24 describe a los impíos finalmente abatidos pese a su prosperidad temporal. Eclesiastés 10:18 lo usa literalmente para el deterioro estructural causado por la negligencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111420, 'spa', 'Redil de ovejas', 'Las traducciones identifican uniformemente recintos para ovejas: español ''rediles, corrales''. El Salmo 50:9 afirma que Dios no necesita ofrendas de los rediles humanos, pues todo le pertenece. El Salmo 78:70 recuerda que Dios tomó a David de los apriscos para pastorear a Israel. Habacuc 3:17 describe la devastación total, incluyendo rediles vacíos, pero el profeta aún confía en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111427, 'spa', 'Micmas (topónimo)', 'Ciudad benjaminita de Micmas, estratégicamente ubicada en un paso estrecho al noreste de Jerusalén, cerca de Geba. Su importancia narrativa principal radica en las guerras filisteas del reinado de Saúl, donde el desfiladero de Micmas fue escenario de la audaz incursión de Jonatán (1 Sam 13:2-23; 14:5, 31). Isaías describe un ejército invasor que deposita su bagaje en Micmas camino a Jerusalén (Isa 10:28). Tras el exilio, la ciudad reaparece entre las localidades repobladas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111441, 'spa', 'Calzoncillos sacerdotales', 'Ropa interior sacerdotal de lino que cubria desde la cintura hasta el muslo, requerida para el servicio ante el altar. Siempre en constructo con פִּשְׁתִּים (''lino'') o בַּד (''lino fino''). Prescrita en la investidura (Ex 28:42), el holocausto diario (Lv 6:10), el Dia de la Expiacion (Lv 16:4) y la vision del templo de Ezequiel (Ez 44:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111442, 'spa', 'Tributo o gravamen', 'Impuesto proporcional sobre el botín de guerra, destinado a fines sagrados. Las seis apariciones se concentran en Números 31:28-41, donde Dios ordena a Moisés exigir un מֶכֶס del botín de la campaña madianita: uno de cada quinientos de la porción de los guerreros (para el SEÑOR por medio del sacerdote, v. 28-29) y uno de cada cincuenta de la porción de la congregación (para los levitas, v. 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111444, 'spa', 'Cubierta (capa protectora)', 'Cubierta (capa protectora): cubierta o capa exterior protectora colocada sobre la estructura del tabernáculo o sus enseres sagrados. Describe las cubiertas de pieles de carnero y cuero fino de la tienda de reunión (Éx 26:14; 35:11; 36:19; 39:34; 40:19) y los envoltorios puestos sobre cada objeto santo — el arca, la mesa, el candelabro, el altar de oro y los utensilios — durante el transporte en el desierto (Nm 3:25; 4:8, 10, 11, 12, 25). La única aparición fuera del tabernáculo es Génesis 8:13, donde Noé retira la cubierta del arca.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111452, 'spa', 'Cubierta o cobertura', 'Aquello que cubre, recubre u oculta, con aplicaciones que abarcan contextos rituales, náuticos, comerciales y mortuorios. Los referentes específicos varían ampliamente —desde cubiertas de barcos hasta sudarios funerarios y la grasa ritual—, pero el término mantiene un sentido general de algo que cubre. Esta flexibilidad refleja la tendencia del hebreo a emplear imágenes concretas con alcance semántico amplio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111453, 'spa', 'La Macpela', 'Lugar de sepultura cerca de Hebrón que comprende un campo y una cueva que Abraham compró a Efrón el hitita por cuatrocientos siclos de plata (Gn 23:9, 17). Sirvió como tumba ancestral durante tres generaciones: Abraham y Sara (Gn 23:19; 25:9), Isaac y Rebeca (Gn 49:30-31), y Jacob y Lea (Gn 50:13). El nombre siempre lleva artículo, lo que sugiere un origen descriptivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111455, 'spa', 'vender (Qal activo)', 'vender (Qal activo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111456, 'spa', 'ser vendido (Nifal pasivo)', 'ser vendido (Nifal pasivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111468, 'spa', 'vendedor (participio Qal sustantivado)', 'vendedor (participio Qal sustantivado)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111474, 'spa', 'venderse (Hitpael reflexivo)', 'venderse (Hitpael reflexivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111518, 'spa', 'Mercancía y valor', 'Los significados abarcan tanto lo comercial como lo valorativo: español ''mercancía'' y ''precio''. Nehemías 13:16 condena a los mercaderes que vendían sus productos en Jerusalén en día de reposo. Números 20:19 registra la oferta de Israel de pagar por el agua consumida al pasar por Edom. Proverbios 31:10 pregunta retóricamente quién hallará una esposa virtuosa, pues su valor excede al de las piedras preciosas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111524, 'spa', 'Tropiezo, obstáculo', 'Tropiezo, obstáculo: aquello que causa tropiezo o caída, en sentido literal y figurado. El fundamento ético aparece en Levítico 19:14, que prohíbe poner obstáculos ante el ciego. Isaías 8:14 lo aplica teológicamente: el SEÑOR mismo se convierte en piedra de tropiezo. Ezequiel concentra el término en la idolatría como tropiezo espiritual (Ez 7:19; 14:3-4; 18:30). El Salmo 119:165 ofrece el corolario positivo para quienes aman la Torá.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111535, 'spa', 'Inscripción, escritura divina', 'Escritura grabada o inscrita, especialmente la escritura divina sobre las tablas de piedra del pacto. En Éxodo 32:16 tanto la caligrafía como el grabado se atribuyen directamente a Dios —מִכְתַּב אֱלֹהִים—, distinguiendo esta escritura sagrada de la composición humana ordinaria. También abarca la inscripción sacerdotal en la placa de oro (Éx 39:30) y la reescritura del Decálogo (Dt 10:4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111540, 'spa', 'Documento escrito, carta', 'Documento escrito producido por agente humano para comunicación o decreto. En 2 Crónicas 21:12, un מִכְתָּב del profeta Elías llega como carta de advertencia, mientras que 2 Crónicas 35:4 lo empareja con כְּתָב para describir las instrucciones escritas de David y Salomón para el servicio del templo. El contexto documental y la autoría humana distinguen este sentido del uso sagrado referido a la escritura divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111544, 'spa', 'Mictam', 'Término técnico de significado desconocido usado exclusivamente en los títulos de salmos (Sal 16:1; 56:1; 57:1; 58:1; 59:1; 60:1), siempre acompañado de ''de David''. La stelographia (''inscripción en columna'') de la Septuaginta sugiere algo grabado o permanente. Estos seis salmos comparten contextos de crisis personal y confianza urgente en Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111547, 'spa', 'estar lleno (estativo)', 'El Qal estativo describe un estado de plenitud: estar lleno de algo. Con 49 apariciones, la tierra está ''llena de violencia'' en tiempos de Noé (Gn 6:13), el templo se llena ''de la gloria del SEÑOR'' (2 Cr 5:13), la casa está ''llena de gente'' (Jue 16:27). A diferencia de la acepción causativa, no requiere agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111548, 'spa', 'llenar (causativo)', 'El Piel causativo hace que algo se llene: llenar activamente un recipiente, espacio o entidad con contenido. Con 90 apariciones, Dios ordena a la humanidad ''llenad la tierra'' (Gn 1:28; 9:1), Rebeca ''llenó su cántaro'' en el pozo (Gn 24:16), Moisés llena cuencos con sangre (Éx 24:6) y las manos de los sacerdotes son ''llenadas'' en la consagración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111549, 'spa', 'ser llenado (pasivo)', 'El Nifal pasivo o medio: ser llenado o llegar a estar lleno como proceso que se experimenta. Con 42 apariciones: la tierra ''se llenó de violencia'' (Gn 6:11), las casas de Egipto ''se llenaron'' de enjambres (Éx 8:21), los israelitas ''llenaron la tierra'' multiplicándose (Éx 1:7). Esta voz gramatical enfoca el resultado del proceso más que el agente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111558, 'spa', 'cumplir, completar', 'Completación temporal y de promesas: cumplir juramentos, completar períodos, llevar propósitos a término. Con 43 apariciones: ''se cumplieron sus días de dar a luz'' (Gn 25:24), Jacob pide a Labán ''cumplir su semana'' nupcial (Gn 29:27-28), Jeremías profetiza ''cuando se cumplan los setenta años'' (Jer 25:12; 29:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111562, 'spa', 'llenar (Qal transitivo)', 'El Qal usado transitivamente, donde lleva fuerza transitiva en lugar de significado estativo. Trece atestiguaciones: Elías ordena ''llenad cuatro cántaros con agua'' (1 R 18:34), Eliseo instruye a la viuda ''llena todas estas vasijas'' (2 R 4:6), el salmista profetiza que Dios ''llenará de cadáveres'' (Sal 110:6). Funcionalmente equivalente al Piel pero con la forma Qal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111568, 'spa', 'engastar (gemas)', 'Acepción técnica especializada en contextos de joyería: engastar o incrustar piedras preciosas en monturas. Tres apariciones: Bezalel es hábil ''en el engaste de piedras'' para las vestiduras sacerdotales (Éx 31:5; 35:33), y las manos del amado se describen poéticamente como ''engastadas de joyas'' (Cnt 5:14).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111575, 'spa', 'seguir plenamente', 'El modismo מִלֵּא אַחֲרֵי (''llenar detrás de'') significa seguir con plena devoción, con 5 apariciones. Dios elogia a Caleb porque ''me siguió plenamente'' (Nm 14:24; 32:11-12; Dt 1:36), y de Salomón se dice que ''no siguió plenamente'' como David (1 R 11:6). La metáfora de ''llenar detrás de alguien'' expresa bellamente la entrega total.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111631, 'spa', 'saciar (apetito)', 'Satisfacer el apetito, el hambre o el deseo: llenar como saciedad. Dos atestiguaciones: Dios desafía a Job ''¿Puedes saciar el apetito de los leoncillos?'' (Job 38:39), y Proverbios observa que no se desprecia al ladrón que roba ''para saciar su apetito cuando tiene hambre'' (Pr 6:30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111639, 'spa', 'plenitud (hápax dudoso)', 'Atestiguación única incierta en Job 20:22: ''En la plenitud de su abundancia estará en estrechez''. La frase בִּמְלֹאת שִׂפְקוֹ es difícil: si se trata de una forma nominal (''plenitud'') o de un sentido verbal es debatido. El hápax impide una clasificación segura, aunque parece describir un estado de abundancia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111698, 'spa', 'a plena voz (modismo)', 'Otra atestiguación única en Jer 4:5: ''Proclamad, hacedlo oír, llenad la voz / a plena voz''. Algunas traducciones lo interpretan como un modismo para proclamar en voz alta o soplar el šofar con fuerza. La construcción única hace incierto si se trata de una acepción distinta o de una extensión de la idea de ''llenar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111699, 'spa', 'agruparse (reflexivo)', 'Último hápax en Job 16:10: ''Han abierto su boca contra mí... se agrupan contra mí''. La forma Hitpael podría significar ''se llenan a sí mismos'' o ''se congregan en masa''. El suajili lo rinde como ''llenarse'' (reflexivo), sugiriendo que la turba ''se llena'' o se amontona. La forma y el contexto únicos dificultan una clasificación segura.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111709, 'spa', 'lleno de, colmado de', 'lleno de, colmado de');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111711, 'spa', 'completo, íntegro, plena medida', 'completo, íntegro, plena medida');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111716, 'spa', 'encinta, embarazada', 'encinta, embarazada');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111724, 'spa', 'a plena voz, en voz alta', 'a plena voz, en voz alta');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111730, 'spa', 'La medida completa o el contenido total de un recipiente, espacio o agrupación', 'La medida completa o el contenido total de un recipiente, espacio o agrupación. Cadenas constructas como ''la plenitud de tus puños'' (Éx 9:8), ''la plenitud del omer'' (Éx 16:33) y ''la plenitud de la tierra'' (Sal 24:1) muestran cómo la palabra indica completitud de cantidad. El español ''lleno de'' y el francés ''plénitude'' reflejan consistentemente esta totalidad cuantitativa. Génesis 48:19 extiende la idea a personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111737, 'spa', 'Grupo completo o contingente de personas reunidas como conjunto íntegro', 'Grupo completo o contingente de personas reunidas como conjunto íntegro. En Isaías 31:4, una ''plenitud de pastores'' es convocada contra un león, no como concepto abstracto de plenitud sino como una compañía concreta de hombres. Esta única aparición representa un desplazamiento metonímico de la cantidad a la colectividad humana.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111751, 'spa', 'consagración sacerdotal', 'El acto y las ofrendas de la ordenación sacerdotal — literalmente ''llenar la mano'', un antiguo modismo para investir a alguien con autoridad. Éxodo 29:22–34 y Levítico 7:37–8:33 detallan el carnero de consagración (אֵיל הַמִּלֻּאִים), el canastillo de panes de ordenación y el rito de instalación de siete días.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111752, 'spa', 'engaste de gemas', 'Montura, engaste o bisel para piedras preciosas — el encaje o marco de filigrana en el cual una gema se ''llena'' o inserta. Éxodo 25:7 enumera ''piedras de engaste'' (אַבְנֵי מִלֻּאִים) entre los materiales del santuario, y 1 Crónicas 29:2 las incluye entre las provisiones de David para el templo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111759, 'spa', 'Plenitud, producción plena', 'Plenitud, producción completa o estado de estar totalmente lleno. Se usa concretamente para el rendimiento agrícola: la cosecha plena del campo o la viña (Éx 22:29, «tu plenitud» como primicias; Dt 22:9, «la plenitud de la semilla»; Nm 18:27, «como la plenitud del lagar»). También se emplea de manera más amplia para una ciudad colmada de cierta cualidad (Is 1:21, «llena de justicia»; 2 S 23:11, un campo).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111767, 'spa', 'Engaste de piedras', 'Las traducciones identifican monturas o engastes para piedras: español ''engaste, monturas''. Éxodo 28:17, 20 detalla las instrucciones para el pectoral del sumo sacerdote con doce piedras engastadas en filigrana de oro, cada una representando una tribu de Israel. Éxodo 39:13 describe la ejecución de estas instrucciones. El engaste cuidadoso de cada piedra preciosa refleja la sacralidad de la obra.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111768, 'spa', 'mensajero, enviado', 'Un agente humano enviado para entregar un mensaje o cumplir una misión diplomática. Jacob envía מַלְאָכִים hacia Esaú (Gn 32:3), Moisés despacha mensajeros al rey de Edom (Nm 20:14), y Rahab oculta a los espías a quienes el rey de Jericó llama מַלְאָכִים (Jos 6:17). El énfasis recae en la función de ser enviado, no en la naturaleza sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111769, 'spa', 'ángel, mensajero divino', 'Ser celestial enviado por Dios, frecuente en la fórmula מַלְאַךְ יהוה (''ángel del SEÑOR''). Se aparece a Agar (Gn 16:7-11), se interpone ante Balaam (Nm 22:22-35) y comisiona a Gedeón (Jue 6:11-22). Las 111 apariciones incluyen ángeles individuales y huestes angélicas, y el ángel del SEÑOR a menudo habla como si fuera Dios mismo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111810, 'spa', 'obra, trabajo, labor', 'Trabajo, labor o tarea en sentido general: la inmensa mayoría con 158 apariciones. Abarca proyectos de construcción (el tabernáculo en Éxodo 35-40, el templo en 1 Reyes 5-7, los muros de Jerusalén en Nehemías), labor agrícola, servicio real, y especialmente la prohibición sabática contra מְלָאכָה (Éx 20:10; 31:14-15; Lv 23:7-8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111818, 'spa', 'artesanía, maestría', 'Artesanía o destreza técnica cualificada: 5 apariciones, concentradas en las narrativas de construcción del tabernáculo. Dios llena a Bezalel de sabiduría para ''toda artesanía'' (Éx 31:3, 5; 35:31), y Ez 28:13 describe la ''factura'' de los engastes del querubín. La distinción frente al trabajo genérico queda marcada interlingüísticamente: el coreano emplea 기술/솜씨 (''pericia/arte'') en lugar del simple 일 (''trabajo'').');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111824, 'spa', 'propiedad, bienes', 'Propiedad o bienes confiados al cuidado de otro: 2 apariciones en Éx 22:8 y 22:11, en el contexto de disputas de propiedad. Cuando alguien reclama que su prójimo se ha apropiado de su ''propiedad'' (מְלָאכָה), el caso se lleva ante Dios o los jueces. Es una extensión metonímica: el trabajo se convierte en la cosa que se posee.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111829, 'spa', 'ganado, posesiones', 'Ganado o posesiones muebles: una única aparición en Gn 33:14, donde Jacob dice a Esaú que viajará despacio ''según el paso del ganado (מְלָאכָה) que va delante de mí''. Los animales son la ''propiedad en movimiento'' de Jacob, los bienes productivos de un jefe seminómada. La aguda divergencia entre las traducciones revela esta acepción pastoral especializada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111838, 'spa', 'negocio, empresa', 'Negocio o empresa comercial: una única aparición en Sal 107:23, describiendo a quienes ''hacen negocio en las grandes aguas''. Aquí מְלָאכָה designa actividad mercantil u ocupación comercial, no labor física. La pregunta de Jon 1:8 ''¿cuál es tu ocupación (מְלָאכָה)?'' sugiere un puente semántico entre labor y quehacer profesional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111846, 'spa', 'Vestimenta, ropa, indumentaria', 'Ropa, vestidura o indumentaria que a menudo señala estatus, identidad o afiliación religiosa. Se emplea para las vestiduras provistas a los adoradores de Baal (2 R 10:22), la impresionante ropa de los siervos de Salomón que asombró a la reina de Sabá (1 R 10:5; 2 Cr 9:4), la indumentaria extranjera que provocó reprensión profética (Sof 1:8), la ropa como signo de riqueza (Job 27:16) y las vestiduras de Dios como guerrero manchadas por el juicio (Is 63:3).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111852, 'spa', 'Molde o estructura ladrillera', 'Relacionado con la fabricación de ladrillos: ya sea el molde que da forma a la arcilla húmeda o la estructura (horno, terraza) vinculada a la producción de ladrillos. Las propiedades preservativas de la sal lo hacían significativo en contextos rituales. La evidencia multilingüe refleja ambigüedad genuina entre «molde» y «horno». Los contextos lo asocian con trabajo forzado, preparación defensiva y estructuras permanentes como la terraza de Tafnes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111853, 'spa', 'El sentido primario', 'El sentido primario: una palabra o conjunto de palabras como unidad de habla. Los amigos de Job ofrecen ''palabras'' de consejo (Job 4:2, 4); Job exige que escuchen ''mis palabras'' (Job 13:17; 19:23); el último oráculo de David comienza ''su palabra estaba en mi lengua'' (2 S 23:2). El español ''palabra(s)'', el francés ''parole'' y el alemán ''Wort'' convergen en el contenido verbal directo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111859, 'spa', 'Estrechamiento especializado hacia ''refrán'' o dicho burlesco', 'Estrechamiento especializado hacia ''refrán'' o dicho burlesco. En Job 30:9, el sufriente Job lamenta ''he llegado a ser su refrán'', una expresión fija y repetible de burla. El español ''refrán'' y el inglés ''byword'' captan el cambio de ''palabra'' neutral a expresión cristalizada usada despectivamente contra alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111865, 'spa', 'Sentido amplio que abarca el habla o discurso sostenido como totalidad', 'Sentido amplio que abarca el habla o discurso sostenido como totalidad. Job 29:22 recuerda un tiempo en que ''después de mi discurso no volvían a hablar''; aquí millah no designa palabras individuales sino el acto completo de elocuencia pública. El español ''dicho'' y el uso colectivo singular lo distinguen del plural distributivo del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111866, 'spa', 'Sustantivo femenino arameo que abarca ''palabra, declaración, mandato'' y ''asunto,', 'Sustantivo femenino arameo que abarca ''palabra, declaración, mandato'' y ''asunto, cosa, cuestión''. Como discurso, va desde decretos reales (Dn 2:5, 8; 3:28; 6:13) hasta las jactancias blasfemas del cuerno pequeño (Dn 7:11, 25). Como ''asunto'', designa temas de investigación o preocupación (Dn 2:10–11, 23; 7:1, 28). En español, ''palabra'' frente a ''asunto'' refleja bien esta doble gama semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111875, 'spa', 'Millo (topónimo/fortificación)', 'Nombre propio derivado de m-l-ʾ (''llenar''), que designa una terraza de relleno o fortificación de terraplén. Dos sitios llevan este nombre: (a) bêth millôʾ cerca de Siquem, sede de la aristocracia local en el episodio de Abimelec (Jue 9:6, 20); (b) hammillôʾ en Jerusalén, fortificación mayor que David inició (2 Sam 5:9; 1 Cr 11:8), Salomón amplió (1 Re 9:15, 24; 11:27) y Ezequías reparó posteriormente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111878, 'spa', 'Maluc', 'Nombre propio masculino portado por varios individuos en la literatura bíblica postexílica: un ancestro levita en la genealogía de cantores del templo (1 Cr 6:44), dos hombres que se divorciaron de esposas extranjeras durante las reformas de Esdras (Esd 10:29, 32), y firmantes del pacto de Nehemías (Neh 10:4, 27).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111880, 'spa', 'Sustantivo abstracto que designa la realeza, el oficio real o la soberanía', 'Sustantivo abstracto que designa la realeza, el oficio real o la soberanía. Se emplea para la realeza recién instaurada de Saúl (1 S 10:16, 25; 11:14), la transferencia de poder a la línea de David (1 R 2:15, 22; 11:35), la soberanía suprema de Dios (Sal 22:28; Abd 21) y, metafóricamente, el esplendor de Jerusalén (Ez 16:13). Frases en estado constructo como ''ciudad real'', ''trono real'' y ''descendencia real'' extienden el término a dominios afines.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111889, 'spa', 'Posada, mesón', 'Posada o campamento nocturno para viajeros. Se usa del mesón donde los hermanos de José abrieron sus costales (Gn 42:27; 43:21), la posada donde Dios confrontó a Moisés (Éx 4:24), el campamento de Israel al cruzar el Jordán (Jos 4:3, 8) y el campamento asirio (Isa 10:29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111899, 'spa', 'Salar o sazonar', 'Aplicar sal a algo, ya sea sazonando ofrendas sacrificiales, preparando incienso o lavando a un recién nacido. Las propiedades conservantes y purificadoras de la sal la hacían significativa en contextos rituales, simbolizando la permanencia del pacto. La práctica de salar a los recién nacidos, aunque ajena al lector moderno, representaba aparentemente un rito de purificación conocido en el antiguo Oriente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111901, 'spa', 'Sal (mineral)', 'Las traducciones identifican uniformemente el mineral ''sal'' en contextos arameos. Esdras 6:9 y 7:22 enumeran la sal entre las provisiones que el tesoro persa suministraba para los sacrificios del templo, mostrando el apoyo real al culto judío. Esdras 4:14 emplea la expresión ''comer la sal del palacio'' para expresar lealtad y obligación hacia el rey. La sal simbolizaba fidelidad y alianza.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111902, 'spa', 'La sustancia mineral en sí, usada para sazonar alimentos (Job 6', 'La sustancia mineral en sí, usada para sazonar alimentos (Job 6:6), purificar aguas (2 R 2:20–21) y especialmente en el ritual sacrificial: Lv 2:13 ordena sal en toda ofrenda de cereal, estableciendo el ''pacto de sal'' (בְּרִית מֶלַח) como metáfora de permanencia (Nm 18:19; 2 Cr 13:5). Esparcida sobre Siquem conquistada (Jue 9:45), simboliza desolación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111903, 'spa', 'La sal como componente de topónimos', 'La sal como componente de topónimos: el Mar de la Sal (yam ha-melaḥ, el Mar Muerto), el Valle de la Sal y la Ciudad de la Sal. Estas expresiones fijas representan aproximadamente la mitad de las ocurrencias. Gn 14:3 identifica el Mar Salado con el Valle de Sidim; Nm 34:3, 12 y Jos 3:16; 15:2, 5 lo usan como marcador fronterizo del territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111913, 'spa', 'Marineros profesionales', 'Navegantes o marineros profesionales que trabajan a bordo de embarcaciones. Los contextos destacan tanto su pericia como su vulnerabilidad ante desastres marítimos, ya sea la tormenta que aterró a los compañeros de Jonás o la catástrofe económica por la caída de Tiro. El origen prestado del término (del asirio malaḫu) subraya el carácter internacional y especializado de la navegación antigua.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111914, 'spa', 'Tierra salada maldita', 'La evidencia multilingüe apunta a tierra arruinada por la sal: «salada, tierra-salada, salar». Job 39:6 describe al asno salvaje habitando yermos salinos. Jeremías 17:6 amenaza con destierro a tierras baldías e inhabitables. Salmo 107:34 muestra la soberanía de Dios al transformar lo fértil en salar y viceversa, subrayando que la sal simboliza juicio y restauración divinos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111915, 'spa', 'guerra, batalla', 'Conflicto armado entre fuerzas opuestas, abarcando batallas individuales y guerras prolongadas. El sustantivo deriva de la raíz ל-ח-מ y aparece en fórmulas teológicas como ''guerras del SEÑOR'' (Nm 21:14; 1 S 18:17) y como acusativo cognado con נִלְחַם (''hacer guerra'', 1 S 8:20). Su alcance va desde la coalición de Gn 14:2 hasta la guerra cósmica profética.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111956, 'spa', 'Nifal', 'Nifal: escapar, huir de un peligro o persecución. El sentido más frecuente, abarcando la autoextracción de un peligro mortal. Lot huye de la destrucción de Sodoma (Gn 19:17, 20, 22); Ehud escapa a Seirá (Jue 3:26); el alma del salmista escapa como ave de la trampa (Sal 124:7). El árabe مَلَصَ (''deslizarse de la mano'') ilumina la imagen central.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111963, 'spa', 'Piel causativo', 'Piel causativo: librar, rescatar, salvar a alguien de un peligro, la muerte o el cautiverio. El agente efectúa activamente la liberación de otro. Mical libra a David de Saúl (1 S 19:11); Dios promete rescatar al fiel (Sal 18:48, 2 S 22:49).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (111993, 'spa', 'Hitpael reflexivo', 'Hitpael reflexivo: librarse o escaparse por esfuerzo propio. Poco frecuente (Job 19:20, 41:19), este reflexivo intensificado enfatiza la iniciativa personal al escapar. Job lamenta haberse escapado ''con la piel de mis dientes'' (Job 19:20), el margen más estrecho de autorescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112004, 'spa', 'Piel/Hifil especializado', 'Piel/Hifil especializado: dar a luz crías, poner huevos. Extensión biológica inesperada de la imagen de ''deslizarse fuera'', hallada solo en Isaías 34:15 (una serpiente que pone y empolla huevos) e Isaías 66:7 (Sion que da a luz antes de tener dolores de parto).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112012, 'spa', 'Un participio Hifil singular en Isaías 31', 'Un participio Hifil singular en Isaías 31:5 que describe a YHWH ''librando'' a Jerusalén, funcionando como un rescate causativo paralelo al sentido 2 pero en forma participial. Se trata de una liberación activa en curso, coherente con el uso más amplio del Piel/Hifil de rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112023, 'spa', 'reinar, ser rey (Qal)', 'Significado básico en Qal: reinar, gobernar como rey, ejercer soberanía real. Abarca la gran mayoría de las apariciones (300x), desde monarcas israelitas (David reinó en Hebrón, 2 Sam 2:10) y reyes extranjeros (listas de reyes edomitas, Gn 36:32ss.) hasta la realeza divina (YHWH reina por siempre, Éx 15:18). Todas las lenguas convergen en un equivalente central: español reinar, francés régner, alemán regieren.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112027, 'spa', 'hacer rey, hacer reinar (Hifil)', 'Sentido causativo en Hifil (49x): instalar a alguien como rey, hacer que reine. Estructuralmente distinto del sentido 1: el sujeto es quien otorga la corona, no quien la porta. Pasajes clave incluyen Jueces 9:6, donde los habitantes de Siquem «hicieron rey a Abimélec», y 1 Samuel 8:22, donde YHWH indica a Samuel que «les haga un rey». El árabe mallaka (Forma II, con reduplicación de la radical media) refleja este mismo patrón causativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112098, 'spa', 'ser hecho rey (pasivo)', 'Una sola aparición en Daniel 9:1, donde una forma Hofal pasiva o de influencia aramea produce el significado «fue hecho rey». Darío el medo «fue hecho rey» (humlak) sobre el reino caldeo. El matiz pasivo tiende un puente entre el hebreo y las secciones arameas de Daniel, donde la raíz mlk aparece con frecuencia en formas pasivas equivalentes.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112104, 'spa', 'rey, gobernante humano', 'Un soberano o monarca humano que gobierna sobre una ciudad-estado, nación o imperio. Incluye a reyes israelitas (Saúl, David, Salomón), reyes extranjeros (Faraón, Nabucodonosor, Ciro) y reyes menores de Canaán. La uniformidad entre lenguas es llamativa: cada idioma emplea su término real básico sin ninguna matización adicional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112125, 'spa', 'Rey, soberano divino', 'Dios o el Mesías como Rey divino, título teológico que expresa la soberanía suprema del SEÑOR. Las glosas multilingües adoptan formas posesivas y devocionales —''Rey de mí'', ''a nuestro Rey''— señalando la relación personal y pactual entre Dios como Rey y su pueblo. Se concentra en los Salmos: ''He establecido a mi Rey en Sion'' (Sal 2:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112143, 'spa', 'Nombre propio benjaminita', 'Nombre masculino propio en la genealogía benjaminita, idéntico en forma al sustantivo común «rey». La evidencia multilingüe muestra confusión entre «rey» y «Mélec», reflejando la ambigüedad genuina de algunos pasajes. El uso como identificador personal junto a su significado como título demuestra la frontera difusa entre vocabulario común y nombres propios en hebreo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112144, 'spa', 'rey', 'Sustantivo arameo para un gobernante soberano o monarca, equivalente en estado determinado del hebreo mélek. Presente abrumadoramente en Daniel y Esdras, designa sobre todo a reyes babilonios (Nabucodonosor, Belsasar) y monarcas persas (Ciro, Darío, Artajerjes). La forma enfática malká constituye la inmensa mayoría de las atestaciones. En Dn 7:17 el plural malkín denota «reinos» por metonimia, mostrando la fluidez del sustantivo entre persona real y entidad política.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112153, 'spa', 'Moloc (deidad pagana)', 'Nombre propio de una deidad cananea/amonita a la que se sacrificaban niños por fuego. Aparece siempre con artículo definido (ha-Molek) y se vincula al rito horrendo de ''pasar por el fuego'' en el Valle de Ben-Hinom (2 R 23:10; Jer 32:35). La legislación levítica (Lv 18:21; 20:2-5) trata la consagración a Moloc como idolatría y homicidio a la vez.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112156, 'spa', 'Vuestro rey (sustantivo)', 'Posible lectura como sustantivo común ''vuestro rey'' en Amós 5:26, donde el texto consonántico malkekhem puede vocalizarse como sustantivo regular con sufijo posesivo en lugar del nombre divino. Esta lectura alternativa encaja con la denuncia profética del liderazgo autoelegido por Israel y su procesión idolátrica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112160, 'spa', 'Milca (nombre propio)', 'Milca, esposa de Nacor e hija de Harán, figura clave en la genealogía de la familia de Abraham. Su matrimonio con Nacor (Gn 11:29) produce ocho hijos, entre ellos Betuel (Gn 22:20, 23), lo que la convierte en abuela de Rebeca. Es mencionada repetidamente en el relato del siervo que busca esposa para Isaac (Gn 24:15, 24, 47), estableciendo el vínculo de parentesco esencial que valida el arreglo matrimonial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112162, 'spa', 'Soberana o consorte real femenina', 'Soberana o consorte real femenina. La palabra designa abrumadoramente a reinas nombradas en la narrativa: la Reina de Sabá que puso a prueba la sabiduría de Salomón (1 R 10:1-13), Vasti rechazando la orden del rey (Est 1:9-19) y Ester intercediendo por Israel (Est 5-9). El plural en Cantares 6:8-9 sitúa a las reinas por encima de las concubinas en la casa real.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112170, 'spa', 'Reino o territorio como entidad política gobernada por un soberano', 'Reino o territorio como entidad política gobernada por un soberano. Este sentido dominante (46 ocurrencias) abarca el imperio babilónico de Nabucodonosor (Dn 2:37), los sucesivos reinos mundiales de la visión de la estatua (Dn 2:39-40) y el reino eterno de Dios (Dn 2:44, 7:27). La forma enfática subraya su carácter concreto como dominio territorial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112173, 'spa', 'Reinado o ejercicio de la autoridad real, enfatizando el aspecto temporal y func', 'Reinado o ejercicio de la autoridad real, enfatizando el aspecto temporal y funcional del gobierno más que el territorio. En Esdras 4:24 y 6:15 aparece en fórmulas de datación: ''en el reinado de Darío''. Daniel 4:17-32 lo emplea para la autoridad regia que se otorga y se quita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112179, 'spa', 'Reinos en plural, refiriéndose a múltiples entidades políticas colectivamente, e', 'Reinos en plural, refiriéndose a múltiples entidades políticas colectivamente, especialmente en contextos apocalípticos. Daniel 2:44 declara que el reino de Dios aplastará ''todos estos reinos'', y 7:23 describe una cuarta bestia que devora ''todos los reinos''. El constructo plural מַלְכְוָת aparece solo tres veces, marcando momentos culminantes donde los imperios individuales ceden ante el dominio universal de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112187, 'spa', 'Reino o territorio como entidad política bajo la soberanía de un rey', 'Reino o territorio como entidad política bajo la soberanía de un rey. El sentido más frecuente (alrededor de dos tercios de las ocurrencias). Se usa de reinos humanos (1 S 20:31; 1 R 2:12) y del reino universal de Dios (Sal 145:11-13). Incluye construcciones posesivas (''su reino'') que enfatizan la relación entre gobernante y territorio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112189, 'spa', 'Realeza o dignidad real como atributo personal', 'Realeza o dignidad real como atributo personal: posición regia, estatus de reina o rango soberano. Este sentido aparece destacadamente en Ester, donde la מַלְכוּת de la reina es su posición y esplendor reales (Est 1:11, 4:14). Capta un matiz abstracto y cualitativo, distinto tanto del territorio como del período de gobierno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112190, 'spa', 'Reinado o período de gobierno, enfatizando la dimensión temporal o activa más qu', 'Reinado o período de gobierno, enfatizando la dimensión temporal o activa más que el territorio. Crónicas emplea frecuentemente este sentido en fórmulas cronológicas (''en el reinado de...''), como en 1 Cr 26:31 y 2 Cr 3:2. El contexto distingue el ejercicio dinámico del poder de la mera referencia geográfica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112222, 'spa', 'Nombre propio masculino', 'Este nombre propio se transliteró como «Malquiel» o «Malkiel» en diversas traducciones. Génesis 46:17 lo incluye entre los descendientes de Jacob que fueron a Egipto. Números 26:45 lo identifica como cabeza ancestral del clan malquielita dentro de Aser. 1 Crónicas 7:31 repite su nombre en la genealogía de Aser, confirmando su lugar permanente en el registro tribal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112224, 'spa', 'El nombre propio teofórico Malquiyá/Malquías (''mi rey es Yah''), que identifica a', 'El nombre propio teofórico Malquiyá/Malquías (''mi rey es Yah''), que identifica a múltiples figuras del AT: un antepasado levita del cantor del templo Asaf (1 Cr 6:40), un sacerdote del turno templario de David al que correspondió la quinta suerte (1 Cr 24:9), el padre del sacerdote Pasjur (1 Cr 9:12; Jer 21:1; 38:1), el príncipe dueño de la cisterna donde fue encarcelado Jeremías (Jer 38:6), hombres que repudiaron esposas extranjeras (Esd 10:25, 31) y reparadores de las murallas de Jerusalén (Neh 3:11, 14, 31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112229, 'spa', 'Hijo del rey Saul', 'Nombre propio que designa a un hijo del rey Saul, caido en la batalla del monte Gilboa. En espanol se traduce Malquisua o Malqui-Sua, reflejando su estructura teoforica bipartita. La LXX ofrece variantes como Melcheisa y Melchesoue. Su muerte se registra en 1 S 31:2 y 1 Cr 10:2, y aparece en las genealogias de 1 Cr 8:33 y 9:39.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112231, 'spa', 'Deidad nacional amonita', 'Nombre propio del dios nacional amonita, caracterizado como abominación y asociado con la apostasía de Salomón. Las glosas multilingües preservan el nombre divino (Milcom, Malkam) con variaciones menores. El culto a esta deidad representaba infidelidad al pacto para Israel, especialmente grave cuando el rey más sabio edificó lugares altos para dioses extranjeros con el fin de complacer a sus esposas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112232, 'spa', 'reina del cielo', 'Sustantivo femenino que significa «reina», empleado exclusivamente en la frase constructa «reina del cielo» para designar a una diosa adorada en Judá antes y durante el exilio. Jeremías 7:18 describe la participación de familias enteras en el culto: los hijos recogen leña, los padres encienden fuego y las mujeres amasan tortas con la imagen de la diosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112234, 'spa', 'Hablar o declarar', 'Hablar, declarar o pronunciar palabras, con énfasis en el acto de expresión verbal. Los contextos abarcan desde preguntas retóricas sobre el habla hasta declaraciones de conocimiento, lo que sugiere que el término abarca tanto el habla cotidiana como la proclamación más formal. Su uso en el Salmo 106:2 resalta la magnitud de lo que se intenta expresar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112236, 'spa', 'hablar, proferir', 'Hablar o pronunciar palabras en arameo (conjugación Pael), tanto en conversación ordinaria como en proclamas blasfemas. Daniel 6:21 registra a Darío hablando con Daniel tras la noche en el foso de los leones. Las cuatro apariciones en Daniel 7 (vv. 8, 11, 20, 25) describen el discurso arrogante del cuerno pequeño contra Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112242, 'spa', 'Botín, presa, despojo', 'Botín o despojos tomados en guerra, bienes arrebatados al enemigo. En Números 31:11-12, 26-27, 32 designa los despojos de la campaña madianita, distinguiéndose de los cautivos (shevi) y el despojo general (shalal), repartidos entre soldados y asamblea. En Isaías 49:24-25 aparece retóricamente donde Dios promete liberar a su pueblo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112247, 'spa', 'Lluvia tardía', 'La lluvia tardía o de primavera, que cae en marzo-abril en la tierra de Israel, esencial para la maduración final del grano antes de la cosecha. Constantemente emparejada con el יוֹרֶה (lluvia temprana/otoñal) para describir el ciclo completo de las lluvias estacionales (Dt 11:14; Jer 5:24; Jl 2:23). Usada metafóricamente para la venida confiable de Dios (Os 6:3) y para el favor real (Pr 16:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112254, 'spa', 'Tenazas y despabiladeras', 'Utensilios del templo en forma dual: tenazas para manejar brasas ardientes y despabiladeras para recortar las mechas del candelabro. En Isaías 6:6 un serafín usa tenazas para tomar un carbón vivo del altar; en los textos del tabernáculo (Ex 25:38; 37:23; Nm 4:9) y el inventario del templo de Salomón (1 R 7:49; 2 Cr 4:21) figuran entre los accesorios del candelabro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112264, 'spa', 'Nombre propio persa', 'Nombre propio de un alto funcionario persa en la corte de Asuero. La tradición textual muestra variación entre el ketiv (מומכן) y el qeré (ממוכן), reflejada en las diversas formas del nombre. Su papel como consejero principal en el asunto de Vasti ilustra la estructura jerárquica de la corte persa y la preocupación por el orden social que caracterizaba a la clase gobernante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112267, 'spa', 'venta, transacción', 'El acto o la transacción de vender, empleado casi exclusivamente en la legislación del Jubileo de Levítico 25. Aquí el sustantivo describe la venta en sí — la transferencia de derechos sobre la propiedad — y las condiciones legales bajo las cuales debe efectuarse la redención o la reversión. La expresión mimkar bayit (Lv 25:33) designa la ''venta de casa'' como concepto jurídico compuesto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112272, 'spa', 'mercancía, artículos', 'Los bienes concretos o mercancías puestos a la venta, desplazando el sentido de la transacción hacia los objetos comercializados. Atestiguado en Nehemías 13:20, donde mercaderes y vendedores de ''toda mercancía'' acampaban fuera de las murallas de Jerusalén en sábado, distinguiendo así los artículos tangibles del acto abstracto de vender que aparece en Levítico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112275, 'spa', 'reino, dominio', 'Territorio político, estado o nación bajo gobierno real (112x): el dominio concreto sobre el cual un rey ejerce autoridad. Abarca desde el reino de Sijón (Dt 3:4, 10, 13) hasta los grandes reinos de la tierra (Sal 46:6; Is 14:16). Todas las lenguas principales emplean términos territoriales concretos: español el reino, francés le royaume, alemán das Königreich. El plural mamlajot aparece con frecuencia en oráculos proféticos que enumeran naciones.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112281, 'spa', 'realeza, soberanía real', 'Ejercicio abstracto de la autoridad real, la soberanía o el reinado (5x), centrado en el oficio y la función de gobernar más que en el territorio. Segundo de Crónicas agrupa varias instancias: la consolidación de «la realeza» por parte de Joram (2 Cr 21:4), la incapacidad de la casa de Ocozías para retener «el reino» como poder real (2 Cr 22:9), y la reivindicación de Abías de que Judá posee la «realeza» legítima (2 Cr 13:8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112307, 'spa', 'Reino, reinado, dominio', 'Reino, reinado o dominio real: el ámbito del gobierno territorial de un rey o el período de su autoridad soberana. Josué 13 concentra seis de las nueve apariciones, todas referidas a los reinos transjordanos de Og, rey de Basán (13:12, 30, 31), y de Sijón, rey de los amorreos (13:21, 27). Los usos restantes abarcan tanto la dimensión espacial como la temporal del poder monárquico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112311, 'spa', 'Mamre (nombre propio)', 'Nombre propio que funciona tanto como antropónimo (un confederado amorreo de Abraham, Gn 14:13, 24) como topónimo cercano a Hebrón, asociado con la residencia de Abraham y el sepulcro patriarcal. La expresión ʾēlōnê mamrēʾ (''encinos de Mamre'', Gn 13:18; 18:1) señala la morada principal de Abraham. En la fuente Sacerdotal, Mamre identifica el lugar de la cueva de Macpela donde fueron sepultados Sara, Abraham, Isaac, Rebeca, Jacob y Lea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112315, 'spa', 'dominio soberano', 'Autoridad soberana abstracta: el ejercicio del poder de gobierno sobre un territorio o pueblo. Aparece como acusativo cognado con «gobernar» en Dan 11:3, describiendo el vasto dominio de un rey poderoso, y predicativamente en Dan 11:5 de aquel cuya autoridad excede la de otro. También atestiguado en 2 Re 20:13 y 2 Cr 32:9.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112316, 'spa', 'dominio, autoridad', 'Autoridad soberana, dominio o jurisdicción, ya sea ejercida por cuerpos celestes (Gn 1:16, el ''gobierno'' del sol y la luna sobre el día y la noche), reyes humanos (1 R 9:19, el reino de Salomón; 2 Cr 32:9, el poderío imperial de Senaquerib; Jer 34:1, reinos bajo Nabucodonosor) o Dios mismo (Sal 103:22; 114:2; 145:13). Miqueas 4:8 profetiza la restauración del antiguo dominio a la hija de Sion.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112330, 'spa', 'maná', 'El alimento provisto divinamente durante el período del desierto, una sustancia semejante al pan que aparecía con el rocío matutino (Éx 16:14; Nm 11:9) y sabía a hojuelas con miel (Éx 16:31) o a aceite fresco (Nm 11:8). Central en las narrativas de formación de Israel: provisión diaria y disciplina sabática (Éx 16:15–35), preservación como memorial (Éx 16:33) y lección teológica sobre la dependencia de la palabra de Dios (Dt 8:3, 16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112334, 'spa', '¿Quién? quienquiera', 'Pronombre interrogativo arameo que significa ''¿quién?'' y, en combinación con dî, pronombre relativo indefinido que significa ''quienquiera.'' Usado en Esdras 5:3, 4, 9 para indagaciones oficiales persas (''¿quién os dio autoridad?'') y a lo largo de Daniel tanto para preguntas directas como para decretos condicionales. La forma enfática man-hûʾ ʾĕlāh dî de Nabucodonosor (''¿quién es el dios que...?'' Dan 3:15) emplea la forma reforzada con hûʾ como recurso retórico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112337, 'spa', 'partitivo y ablativo', 'Preposición con valor partitivo y ablativo: «de», «desde», «parte de». Expresa origen, separación o pertenencia parcial. En la visión de Daniel sobre el reino mixto (Dan 2:41-42), transmite la idea partitiva de composición: «en parte de hierro, en parte de barro». Las cinco apariciones confirman esta lectura partitiva, donde la preposición indica tanto procedencia como fracción de un todo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112338, 'spa', 'origen o separación', 'El sentido ablativo dominante que expresa origen, procedencia o separación: ''de'', ''desde'', ''fuera de'', y que representa aproximadamente 1198 de las 1226 apariciones. Es el significado espacial fundamental: Adán es formado ''del'' polvo (Gn 2:7), Eva es tomada ''del'' costado de Adán (Gn 2:22), la ofrenda de Caín sube ''de'' la tierra (Gn 4:10). Rige tanto la partida física como la procedencia abstracta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112353, 'spa', 'comparativo (más que)', 'El uso comparativo, conocido tradicionalmente como el מִן de comparación: ''más que'', ''mayor que'', con aproximadamente 22 apariciones. En Gn 26:16 Abimélec dice a Isaac ''eres más poderoso que nosotros''; en Éx 1:9 el Faraón advierte que los israelitas son ''más numerosos y fuertes que nosotros''; en Dt 1:28 los anaceos son ''más grandes que nosotros''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112363, 'spa', 'partitivo (algo de)', 'El uso partitivo que significa ''algo de'', ''parte de'', ''uno de'', con aproximadamente 3 apariciones en este subconjunto flexivo (Dt 9:14; 2 Cr 25:13; Job 4:12). En Job 4:12 Elifaz dice ''una palabra me fue traída furtivamente, y mi oído captó un susurro de ella'': el partitivo ''algo de'' indica recepción parcial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112366, 'spa', 'causal o referencial', 'El uso causal o temático que significa ''a causa de'', ''por motivo de'', ''acerca de'', con aproximadamente 3 apariciones (1 S 17:50; 2 R 6:1; Sal 65:3). En 2 R 6:1 los profetas dicen que el lugar ''es estrecho para nosotros'' (מִן expresa la causa de la restricción); en Sal 65:3 ''las iniquidades prevalecen sobre mí'', donde la preposición indica la causa abrumadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112376, 'spa', 'de, desde (origen)', 'Sentido ablativo-originativo principal: «de», «desde», «a causa de», marcando procedencia espacial, temporal o causal. Cubre la inmensa mayoría de las apariciones en Esdras y Daniel, con diversos sufijos pronominales (minnéh «de él», minhón «de ellos») y waw conjuntiva opcional. El español de, el francés de y el alemán von traducen uniformemente este sentido.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112382, 'spa', 'parte de (partitivo)', 'Sentido partitivo: «parte de», «algo de», indicando una porción o subconjunto de un todo mayor. La visión de la estatua en Daniel ofrece los ejemplos clásicos: los pies «en parte de hierro y en parte de barro» (Dn 2:33, 41, 42), presentes tanto en el qeré como en el ketiv. El español parte de ellos y el alemán von ihnen preservan con precisión este matiz partitivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112388, 'spa', 'contra (adversativo)', 'Sentido adversativo poco frecuente: «contra» o «sobre», expresando oposición o acción hostil en lugar de origen. Esdras 7:26 ofrece el único caso claro, prescribiendo un castigo «contra él» que desobedezca la ley. Este uso, aunque marginal, tiene paralelo en el ocasional min adversativo del hebreo bíblico y en ciertos dialectos arameos tardíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112393, 'spa', 'contar, ajustar cuentas', 'Contar, calcular, llevar cuenta. En Dan 5:26 (mene, mene), Dios ha «contado» los días del reino de Belsasar, es decir, los ha sumado hasta su fin. Este sentido enfatiza la finalidad y el juicio divino más que la mera aritmética: contar aquí equivale a decretar el término de algo, como confirman las traducciones en español y francés.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112394, 'spa', 'Contado por Dios', 'Este término aparece transliterado como «MENE» en la mayoría de las traducciones, conservando el misterio y el dramatismo de la escena original. Daniel 5:25 lo registra escrito dos veces en la pared del palacio. Daniel 5:26 ofrece la interpretación basada en la raíz verbal «contar»: Dios ha contado los días de Belsasar y del reino, hallándolos completos. Esa misma noche la profecía se cumplió.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112396, 'spa', 'Capacidad de comprender', 'Capacidad mental para el conocimiento y la comprensión, particularmente como don divino. Las cuatro apariciones en Daniel enfatizan el conocimiento como algo otorgado por Dios, ya sea a Daniel para la interpretación de sueños o restaurado a Nabucodonosor tras el juicio divino. El término abarca tanto el contenido del saber como la facultad misma de entender.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112397, 'spa', 'Designar, asignar, destinar', 'Designar, asignar, destinar: 10 ocurrencias en el Piel y ocasionalmente en Qal con fuerza volitiva. Aquí el desplazamiento semántico de ''contar'' a ''asignar'' es completo: Dios ''destina'' a los infieles a la espada (Is 65:12), el rey ''asigna'' provisiones diarias (Dn 1:5), y el Dios de Jonás ''dispone'' un gran pez, una planta, un gusano y un viento (Jon 1:17; 4:6–8).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112398, 'spa', 'Contar, numerar, calcular', 'Contar, numerar, calcular: el sentido activo básico del Qal en 11 ocurrencias. Los sujetos enumeran objetos concretos o metafóricos: granos de polvo (Gn 13:16), el pueblo de Jacob (Nm 23:10), dinero (2 R 12:10), estrellas (Sal 147:4), rebaños que pasan bajo la mano del pastor (Jer 33:13) y días (Sal 90:12).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112401, 'spa', 'Ser designado', 'Ser designado: una única ocurrencia en Pual (pasivo intensivo) en 1 Crónicas 9:29, donde ciertos levitas ''fueron designados'' sobre los utensilios y enseres del santuario. El Pual indica que el nombramiento fue formalmente impuesto por una autoridad externa, distinto del Piel activo ''designar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112407, 'spa', 'Ser contado, ser numerado', 'Ser contado, ser numerado: el Nifal pasivo, con 6 apariciones. El tono teológico es frecuentemente de abundancia inconmensurable: la descendencia de Abraham ''no podrá ser contada'' (Gn 13:16), los animales reunidos por Salomón ''no pudieron ser numerados'' (1 R 8:5; 2 Cr 5:6), y lo torcido ''no puede contarse'' entre lo recto (Ec 1:15).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112418, 'spa', 'Unidad de peso', 'Unidad de peso y valor monetario para oro y plata. En la economía del templo de Salomón, tres minas de oro cubrían cada escudo (1 R 10:17). Los exiliados retornados contribuyeron miles de minas de plata para la reconstrucción (Esd 2:69; Neh 7:71-72). Ezequiel fija la mina en 50 siclos (Ez 45:12), subrayando su naturaleza como medida de masa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112420, 'spa', 'porción, ración', 'Una porción o parte asignada de alimento, ya sea sacrificial, festivo o real. En la legislación sacerdotal designa la parte asignada al sacerdote del animal ofrendado (Éx 29:26; Lv 7:33; 8:29). En contextos domésticos y narrativos se refiere a porciones repartidas en comidas como expresión de honor o afecto (1 S 1:4-5; 9:23). Se extiende al obsequio festivo de porciones de alimento en celebraciones comunitarias (Neh 8:10, 12; Est 9:19, 22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112431, 'spa', 'Reposo, descanso (abstracto)', 'Reposo o seguridad como estado abstracto: el cese de vagar, trabajar o sufrir. El anhelo de Noemí de que Rut halle «reposo» (Rut 3:1) no significa mero sueño, sino la seguridad estable del matrimonio y el hogar. El salmista con «vuelve a tu reposo, alma mía» (Sal 116:7) confirma este sentido de paz asentada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112433, 'spa', 'Lugar de descanso (concreto)', 'Ubicación concreta y física donde uno puede posarse, asentarse o morar con seguridad. Génesis 8:9 ofrece la imagen emblemática: la paloma de Noé «no halló lugar de descanso para la planta de su pie». Deuteronomio 28:65 repite la frase en las maldiciones del pacto, e Isaías 34:14 extiende la imagen a la desolación de Edom.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112435, 'spa', 'El nombre personal del padre de Sansón, un danita de Zora cuya narración ocupa J', 'El nombre personal del padre de Sansón, un danita de Zora cuya narración ocupa Jueces 13 y concluye en 16:31. Su nombre, de la raíz נוח (''descansar''), contrasta irónicamente con la vida turbulenta de su hijo. Se lo presenta como piadoso y aprensivo, ofreciendo sacrificio y temiendo la muerte tras la teofanía (Jue 13:19-22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112438, 'spa', 'Lugar concreto de reposo o morada establecida donde el descanso se materializa', 'Lugar concreto de reposo o morada establecida donde el descanso se materializa. Central en la teología del espacio sagrado: el lugar de reposo de Dios en Sión (Sal 95:11; 132:8, 14; Is 66:1), el lugar de reposo del arca (Nm 10:33; 1 Cr 28:2) y el lugar de reposo del Mesías que será glorioso (Is 11:10). Dt 12:9 lo empareja con ''la herencia'' (נַחֲלָה), haciendo de la Tierra Prometida misma la מְנוּחָה.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112439, 'spa', 'Descanso abstracto, reposo o tranquilidad', 'Descanso abstracto, reposo o tranquilidad: alivio del trabajo, el conflicto o la peregrinación. Gn 49:15 describe la tierra como buena y la מְנוּחָה como agradable; Rut 1:9 la usa para la seguridad que Noemí desea a sus nueras en nuevos matrimonios; Jue 20:43 retrata un respiro militar. En 2 S 14:17 la mujer sabia de Tecoa invoca la מְנוּחָה como la paz que la palabra de un rey puede traer. Las ''aguas de reposo'' del Sal 23:2 evocan tranquilidad pastoral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112458, 'spa', 'Refugio, lugar seguro', 'Un refugio, amparo o lugar de escape: el destino al que se huye en busca de seguridad y protección. Aplicado a Dios mismo como refugio supremo en 2 Samuel 22:3 («mi refugio», en paralelo con «mi fortaleza»), Salmo 59:17 y Jeremías 16:19 («mi refugio en el día de la angustia», en paralelo con «mi fuerza» y «mi fortaleza»).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112461, 'spa', 'Huida, fuga', 'La huida, el acto o proceso de escapar, referido a la acción física de correr en lugar del lugar de seguridad. En Jeremías 46:5 los guerreros egipcios son derrotados y «la huida pereció de ellos» (אָבַד מָנוֹס מִנֶּהֶם), y Amós 2:14 anuncia que «al ligero le faltará la huida».');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112465, 'spa', 'Enjulio del telar', 'Término técnico para la vara cilíndrica del telar que sostiene los hilos de la urdimbre, empleado en las Escrituras como referente de comparación para astas de lanza inusualmente grandes. La frase «como enjulio de tejedor» se convirtió en la expresión convencional para describir las armas de los gigantes, evocando su grosor y peso extraordinarios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112466, 'spa', 'El candelabro dorado de siete brazos (menorá) del Tabernáculo o Templo, un mobil', 'El candelabro dorado de siete brazos (menorá) del Tabernáculo o Templo, un mobiliario ritual sagrado. El hebreo lo asocia consistentemente con el oro y otros objetos cultuales; el español ''candelabro'' y el alemán ''Leuchter'' captan la cualidad formal y ornamental. Las especificaciones detalladas en Éxodo 25:31-40 y su ubicación prominente en la literatura sacerdotal confirman su centralidad litúrgica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112473, 'spa', 'Candelero doméstico ordinario, una pieza de mobiliario del hogar', 'Candelero doméstico ordinario, una pieza de mobiliario del hogar. En 2 Reyes 4:10 la sunamita coloca un candelero junto a una cama, mesa y silla en la habitación del profeta, enseres cotidianos. La visión del candelabro de Zacarías (Zac 4:2) se sitúa entre lo doméstico y lo profético, tomando este objeto sencillo del hogar como vehículo de simbolismo divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112483, 'spa', 'ofrenda de grano (cultual)', 'Ofrenda de grano técnica del culto sacerdotal, el sentido dominante con 139 apariciones, concentrada en Levítico, Números y Ezequiel. Levítico 2 define minjá como flor de harina con aceite e incienso: una porción se quema sobre el altar y el resto lo comen los sacerdotes (Lv 2:1-3). El término se extiende al componente de grano que acompaña los sacrificios de animales (Nm 15:4-9; 28-29).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112484, 'spa', 'ofrenda, oblación (cultual general)', 'Cualquier ofrenda o oblación presentada a Dios (39x) donde minjá designa un don cultual general sin restricción específica al grano. El ejemplo paradigmático es Génesis 4:3-5, donde tanto la ofrenda vegetal de Caín como la animal de Abel se llaman minjá, demostrando que la palabra precede a su especialización levítica. De modo similar, en Jueces 6:18 Gedeón prepara una minjá que incluye carne y caldo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112494, 'spa', 'regalo, presente (secular)', 'Regalo o presente secular entre personas (18x), sobre todo en las narrativas del Génesis. El elaborado presente de Jacob para apaciguar a Esaú (Gn 32:14-22) es el ejemplo clásico: envía rebaños en oleadas como minjá esperando «cubrir su rostro». Los hermanos llevan minjá al funcionario egipcio que resulta ser José (Gn 43:11, 25-26). El árabe se decanta claramente por hadiyya («regalo»), sin recurrir a vocabulario cultual.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112495, 'spa', 'tributo (político, vasallático)', 'Tributo político obligatorio de un vasallo o súbdito a un soberano (15x), en Jueces, Samuel, Reyes y Crónicas. El tributo de Ehud a Eglón (Jue 3:15-18) es el arquetipo narrativo; los moabitas y arameos vencidos llevan minjá a David (2 Sam 8:2, 6); reyes sometidos traen tributo a Salomón (1 Re 5:1). El árabe emplea jizya o kharaj («impuesto, tributo») y el español se decanta por tributo en estos contextos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112541, 'spa', 'Nombre propio, Menahem', 'El nombre personal Menahem, portado exclusivamente por el rey israelita que tomó el poder mediante un golpe contra Salum (2 R 15:14) y reinó aproximadamente entre 752-742 a.C. Las ocho apariciones se concentran en el bloque narrativo de 2 Reyes 15:14-23. Las traducciones multilingües son consistentes: «Menachem» en inglés, «Menahem» en español, reflejando una transliteración directa del hebreo מְנַחֵם.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112546, 'spa', 'Nombre sacerdotal propio', 'Este nombre propio presenta variantes: «Miniamín, Minyamín, Mijamín» en distintos textos y traducciones. 2 Crónicas 31:15 identifica a uno que distribuyó fielmente las ofrendas a los sacerdotes durante las reformas de Ezequías. Nehemías 12:17 y 41 mencionan sacerdotes con este nombre en contextos postexílicos, participando en ceremonias de dedicación. Las variaciones pueden representar individuos diferentes o variantes textuales.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112550, 'spa', 'Sentido activo del Qal', 'Sentido activo del Qal: retener, impedir o privar deliberadamente algo a alguien. El sujeto ejerce control: Dios retiene la lluvia (Am 4:7) y el fruto del vientre (Gn 30:2); Abigail alaba a Dios por haber impedido a David derramar sangre (1 S 25:26, 34). Proverbios 11:26 condena al que retiene el grano, y Pr 3:27 exhorta a no retener el bien al necesitado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112558, 'spa', 'Sentido pasivo del Nifal', 'Sentido pasivo del Nifal: ser retenido, impedido o privado de ocurrir. Se usa cuando el agente de la restricción queda en segundo plano: las lluvias son retenidas en Jer 3:3, la luz de los impíos es contenida en Job 38:15, y las ofrendas cesan en Joel 1:13. Balac dice a Balaam que nada debe ser retenido de su honra (Nm 22:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112574, 'spa', 'Cerradura, cerrojo, tranca', 'Mecanismo de cerrojo o cerradura para asegurar una puerta o portón. En Nehemías (Neh 3:3, 6, 13, 14, 15) aparece en la frase formulaica «sus puertas, sus cerraduras y sus barras», describiendo la restauración de las fortificaciones de Jerusalén. En Cantares 5:5 se refiere al cerrojo de la puerta en un contexto íntimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112580, 'spa', 'Vasijas rituales sagradas', 'Tazones o jarros sacrificiales empleados en el ritual del tabernáculo y del templo, asociados particularmente con la mesa de los panes de la proposición. Su aparición constante en contextos sagrados los distingue como implementos rituales y no como cerámica doméstica común, formando parte del elaborado sistema de vasijas que equipaba el culto israelita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112581, 'spa', 'Manasés (nombre propio)', 'El nombre propio Manasés (מְנַשֶּׁה), que abarca al individuo (primogénito de José, Gn 41:51; 48:1-20), la tribu israelita descendiente de él, su territorio tanto al este como al oeste del Jordán (Jos 17; Nm 32), y portadores posteriores del nombre, incluido el rey Manasés de Judá. Las glosas multilingües son transliteraciones coherentes: español Manasés, francés Manassé, alemán Manasse.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112587, 'spa', 'manasita (gentilicio)', 'Adjetivo gentilicio «el manasita» (הַמְנַשִּׁי), usado como sustantivo demónimo para identificar a un miembro o descendiente de la tribu de Manasés. Atestiguado una sola vez en 1 Crónicas 27:21, donde designa a un oficial tribal. El español el de Manasés y el alemán der Manasse reflejan el paso de nombre personal a identificador colectivo-étnico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (112594, 'spa', 'Gentilicio de Manasés', 'Adjetivo étnico-geográfico que significa «de Manasés» o «manasita», referido especialmente a la media tribu oriental. Se emplea en contextos legales (ciudades de refugio), militares (conquista territorial) y administrativos (asignaciones levíticas), lo cual refleja la identidad distintiva y persistente de esta tribu aun después de su asentamiento.');